select is(pcm.sso_reservar_ingestao_foto_interno('17890000-0000-0000-0000-000000000041','17890000-0000-0000-0000-000000000021','a',repeat('a',64))->>'estado','pendente','repetição não gera nova reserva');
select throws_ok($$select pcm.sso_reservar_ingestao_foto_interno('17890000-0000-0000-0000-000000000041','17890000-0000-0000-0000-000000000021','a',repeat('b',64))$$,'23505',null,'digest divergente conflita');
